const items = $input.all();
const RATING_THRESHOLD = 4.5;
const results = [];

for (const item of items) {
    const root = item.json;
    const p = (root && root.data && root.data.amazonProduct) ? root.data.amazonProduct : root;
    if (!p || !p.asin) continue;

    const rating = p.rating || -1;
    const reviewCount = p.ratingsTotal || 0;
    const currentPrice = (p.price && p.price.value) ? p.price.value : -1;

    const inStock = !!(p.availability && p.availability.status === 'IN_STOCK');

    const highRating = rating > 0 && rating >= RATING_THRESHOLD && reviewCount > 0;

    if (!highRating) continue;

    results.push({
          json: {
                  asin: p.asin,
                  title: p.title || '',
                  reason: 'Producto 5 estrellas',
                  priority: 2,
                  currentPrice: currentPrice > 0 ? currentPrice.toFixed(2) : 'N/A',
                  ratingStars: rating.toFixed(1),
                  reviewCount: reviewCount,
                  inStock: inStock,
                  url: p.link || ('https://www.amazon.com/dp/' + p.asin)
          }
    });
}

return results;

