const woo = $json;
const p = $('Re-fetch producto por ASIN').item.json;

const prompt = `Eres redactor de e-commerce para GearsGarage, tienda de accesorios automotrices. Responde SOLO con JSON valido, sin texto extra, con esta estructura exacta:
{"review_title":"titulo llamativo, max 60 caracteres","review_body":"resena de 150-200 palabras en espanol, tono cercano y experto","ig_caption":"caption Instagram con emojis y hashtags","tiktok_caption":"caption corto para TikTok con hashtags, max 150 caracteres","fb_caption":"caption Facebook con llamada a la accion"}

Producto: ${p.title}
Marca: ${p.brand}
Precio: $${p.price && p.price.value}
Rating: ${p.rating}/5 (${p.ratingsTotal} reviews)
Link: ${p.link}`;

return [{ json: { productId: woo.id, prompt, encodedPrompt: encodeURIComponent(prompt) } }];

const raw = $input.item.json;
let text;
if (typeof raw === 'string') {
    text = raw;
} else if (typeof raw.data === 'string') {
    text = raw.data;
} else if (raw.review_title) {
    text = null;
} else {
    text = JSON.stringify(raw);
}

let parsed;
if (!text) {
    parsed = raw;
} else {
    try {
          parsed = JSON.parse(text);
    } catch (e) {
          const match = text.match(/\{[\s\S]*\}/);
          if (match) {
                  try { parsed = JSON.parse(match[0]); } catch (e2) { parsed = null; }
          }
    }
}

if (!parsed) {
    parsed = {
          review_title: 'Nuevo producto GearsGarage',
          review_body: text || 'No se pudo generar el copy automaticamente.',
          ig_caption: '',
          tiktok_caption: '',
          fb_caption: ''
    };
}

const productId = $('Preparar prompt IA').item.json.productId;

return [{ json: { productId, review_title: parsed.review_title, review_body: parsed.review_body, ig_caption: parsed.ig_caption, tiktok_caption: parsed.tiktok_caption, fb_caption: parsed.fb_caption } }];

let p;
try {
  p = $('Re-fetch producto por ASIN').item.json.data.amazonProduct;
} catch (e) {
  const wc = $json;
  const desc = wc.description || '';
  const brand = desc.includes(' - ') ? desc.split(' - ')[0].trim() : '';
  p = { brand, title: wc.name || '', mainImageUrl: (wc.images && wc.images[0] && wc.images[0].src) || '' };
}
const productId = $json.id;

const productName = `${p.brand || ''} ${p.title}`.trim();
const shortName = productName.length > 60 ? productName.slice(0, 57) + '...' : productName;

const scenes = [
  {
    text: `Professional commercial advertisement video for ${productName}, opening hook close-up shot, smooth dolly zoom into the product, studio lighting with dramatic highlights, premium automotive brand commercial style, upbeat energetic pacing`,
    caption: shortName
  },
  {
    text: `Professional commercial advertisement video for ${productName}, dynamic multi-angle product showcase, tracking shot and rotating reveal, clean hero shot to close the video, premium automotive brand commercial style`,
    caption: 'Disponible ahora en GearsGarage.com'
  }
];

return scenes.map((scene, i) => ({
  json: {
    productId,
    clipIndex: i,
    videoPrompt: scene.text,
    caption: scene.caption,
    imageUrl: p.mainImageUrl
  }
}));

