          tiktokCaption: copy.meta_data ? (copy.meta_data.find(m => m.key === 'tiktok_caption') || {}).value : '',
          fbCaption: copy.meta_data ? (copy.meta_data.find(m => m.key === 'fb_caption') || {}).value : '',
          caption: item.json.caption,
          clipIndex: item.json.clipIndex,
    },
    binary: item.binary
}));
    }
}))
}
}

const items = $input.all();

return items
  .filter(item => {
    const meta = item.json.meta_data || [];
    const ready = (meta.find(m => m.key === 'video_ready') || {}).value;
    return ready === 'true' || ready === true;
  })
  .map(item => {
    const p = item.json;
    const meta = p.meta_data || [];
    const igCaption = (meta.find(m => m.key === 'ig_caption') || {}).value || '';
    const videoUrl = (meta.find(m => m.key === 'video_url') || {}).value || '';
    const price = p.price || (p.regular_price || 'N/D');
    const created = p.date_created ? p.date_created.split('T')[0] : '';

    const text = `📦 *${p.name}*\nPrecio: $${price}\nCreado: ${created}\n${p.short_description ? p.short_description + '\n' : ''}${igCaption ? '\n' + igCaption : ''}${videoUrl ? '\n🎬 Video: ' + videoUrl : ''}\n\nWooCommerce ID: ${p.id}`;

    return { json: {
          productId: p.id,
          text,
          permalink: p.permalink
    } };
  });

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const monthKey = now.getFullYear() + '-' + (now.getMonth() + 1);

if (staticData.canopyMonth !== monthKey) {
  staticData.canopyMonth = monthKey;
  staticData.canopyCount = 0;
}

const CAP = 590; // ~$5/mes: 100 gratis + 490 pagados a $0.01 c/u, con margen

staticData.canopyCount = (staticData.canopyCount || 0) + 1;

if (staticData.canopyCount > CAP) {
  throw new Error('Limite mensual de Canopy alcanzado (~$5, ' + CAP + ' requests). Contador: ' + staticData.canopyCount + '. Se resetea el proximo mes.');
}

return $input.all();

