const items = $input.all();
items.sort((a, b) => (a.json.clipIndex || 0) - (b.json.clipIndex || 0));

const merged = { json: {}, binary: {} };
items.forEach((item, i) => {
  const binKey = Object.keys(item.binary || {})[0] || 'data';
  merged.binary['clip' + i] = item.binary[binKey];
  merged.json['caption' + i] = item.json.caption || '';
});
merged.json.productId = items[0].json.productId;

return [merged];

const results = $input.all();
const trigger = $('Telegram Trigger').item.json;
const asin = trigger.callback_query.data.replace('approve_', '');
const validResults = results.filter(r => r.json && r.json.id);
return [{ json: {
  ...trigger,
  asin,
  isDuplicate: validResults.length > 0,
  existingProductId: validResults.length > 0 ? validResults[0].json.id : null
} }];

const results = [];
for (let i = 0; i < items.length; i++) {
  const binaryData = items[i].binary && items[i].binary.data;
  if (!binaryData) { throw new Error('No se encontro binary.data en el item ' + i); }
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  results.push({ json: { ...items[i].json, videoSize: buffer.length }, binary: items[i].binary });
}
return results;
